questionvariables.text:
/* Butterfly survey: two meanings of NA */

n: 20;

/* Pearson correlation */
pearson_calc(A,B):=block(
    [m:length(A),ma,mb,sa,sb,sab],
    ma:sum(A[k],k,1,m)/m,
    mb:sum(B[k],k,1,m)/m,
    sa:sum((A[k]-ma)^2,k,1,m),
    sb:sum((B[k]-mb)^2,k,1,m),
    sab:sum((A[k]-ma)*(B[k]-mb),k,1,m),
    float(sab/sqrt(sa*sb))
);

/* Twenty completed surveys */
distances_sorted: makelist(
    float(k+(rand(9)-4)/10),
    k,1,n
);

/* Two uncompleted surveys near the reserve */
incomplete_distances: [
    float((1+rand(2))/10),
    float((3+rand(2))/10)
];

/* The ten closest completed sites have numerical counts */
observed_distances: makelist(
    distances_sorted[k],
    k,1,10
);

/* Generate realistic variation */
base_count: 40+rand(11);
increase: 1+rand(2);

observed_counts: makelist(
    base_count+increase*k+rand(31)-15,
    k,1,10
);

/* Trial correlations */
r_trial: pearson_calc(
    observed_distances,
    observed_counts
);

r_complete_trial: pearson_calc(
    distances_sorted,
    append(observed_counts,makelist(0,k,1,10))
);

r_all_zero_trial: pearson_calc(
    append(distances_sorted,incomplete_distances),
    append(
        observed_counts,
        makelist(0,k,1,12)
    )
);

/* Keep variants with distinguishable results */
while not (
    r_trial >= 0.2
    and r_trial <= 0.45
    and r_complete_trial <= -0.6
    and abs(r_all_zero_trial-r_complete_trial) >= 0.02
) do (
    observed_counts: makelist(
        base_count+increase*k+rand(31)-15,
        k,1,10
    ),

    r_trial: pearson_calc(
        observed_distances,
        observed_counts
    ),

    r_complete_trial: pearson_calc(
        distances_sorted,
        append(observed_counts,makelist(0,k,1,10))
    ),

    r_all_zero_trial: pearson_calc(
        append(distances_sorted,incomplete_distances),
        append(
            observed_counts,
            makelist(0,k,1,12)
        )
    )
);

/* Completed surveys */
clean_counts_sorted: append(
    observed_counts,
    makelist(0,k,1,10)
);

recorded_counts_sorted: append(
    observed_counts,
    makelist("",k,1,10)
);

/* Add the two uncompleted surveys */
all_distances: append(
    distances_sorted,
    incomplete_distances
);

all_recorded_counts: append(
    recorded_counts_sorted,
    ["",""]
);

all_statuses: append(
    makelist("Completed",k,1,20),
    ["Not completed","Not completed"]
);

/* Shuffle all 22 rows together */
row_order: random_permutation(
    makelist(k,k,1,22)
);

distances_csv: makelist(
    all_distances[row_order[k]],
    k,1,22
);

recorded_counts: makelist(
    all_recorded_counts[row_order[k]],
    k,1,22
);

survey_status: makelist(
    all_statuses[row_order[k]],
    k,1,22
);

sites: makelist(
    sconcat("S",k),
    k,1,22
);

/* Downloadable CSV */
lab: [
    "Site",
    "Distance_km",
    "Butterfly_count",
    "Survey_status"
];

data: makelist(
    [
        sites[k],
        distances_csv[k],
        recorded_counts[k],
        survey_status[k]
    ],
    k,1,22
);

/* Correlation after deleting every NA row */
r_omitted: pearson_calc(
    observed_distances,
    observed_counts
);

/* Correct: completed surveys only, with documented zeros */
r_clean: pearson_calc(
    distances_sorted,
    clean_counts_sorted
);

/* Incorrect: replace absolutely every NA with zero */
r_all_zero: pearson_calc(
    all_distances,
    append(clean_counts_sorted,[0,0])
);

/* Rounded answers */
r_omitted_display:
    float(round(1000*r_omitted)/1000);

r_clean_display:
    float(round(1000*r_clean)/1000);

r_all_zero_display:
    float(round(1000*r_all_zero)/1000);

/* Variables for the correct scatterplot */
plot_distances: distances_sorted;
plot_counts: clean_counts_sorted;

/* Variables for the incorrect all-zero scatterplot */
plot_all_distances: all_distances;

plot_all_counts: append(
    clean_counts_sorted,
    [0,0]
);
